#!/bin/bash
# run_vsim.sh — Open a Phonon Animation .ascii File with V_Sim
#
# Prerequisites
# -------------
#   - v_sim  (crystal structure visualiser with animation support)
#     Install: https://inac.cea.fr/L_Sim/V_Sim/
#   - An X11 display (DISPLAY must be set, or XWayland must be running).
#     On Wayland compositors, set GDK_BACKEND=x11 (done automatically below).
#
# Usage
# -----
#   Run from a directory containing one or more .ascii animation files
#   (e.g. those generated by animate_phonons.sh or phonopy-load --anime):
#
#     bash run_vsim.sh
#
#   A numbered menu will appear; enter the index of the file to open.
#   Press Ctrl-C to abort without opening a file.

# ---------------------------------------------------------------------------
# Dependency check
# ---------------------------------------------------------------------------
if ! command -v v_sim &>/dev/null; then
    echo "Error: 'v_sim' not found. Please install V_Sim and ensure it is in PATH." >&2
    exit 1
fi

# ---------------------------------------------------------------------------
# Discover .ascii files
# nullglob prevents the literal string '*.ascii' appearing when no files match
# ---------------------------------------------------------------------------
shopt -s nullglob
ASCII_FILES=(*.ascii)
shopt -u nullglob

if [[ ${#ASCII_FILES[@]} -eq 0 ]]; then
    echo "No .ascii files found in $(pwd)." >&2
    exit 1
fi

# ---------------------------------------------------------------------------
# Interactive file selection
# ---------------------------------------------------------------------------
echo "Select an animation file to open with V_Sim:"
select FILE in "${ASCII_FILES[@]}"; do
    if [[ -n "$FILE" ]]; then
        echo "Opening $FILE in V_Sim..."
        export GDK_BACKEND=x11
        v_sim "$FILE" || echo "Error: v_sim failed to launch." >&2
        break
    else
        echo "Invalid selection. Try again."
    fi
done
